  add('ia',['idioma','translate','Amazon Translate','Traducción automática de idiomas.','Traducción / idiomas / multilingüe.','Translate traduce texto entre idiomas con modelos neuronales, sin construir un modelo propio.','Cuando el examen pide traducir contenido o atender usuarios en varios idiomas.','No es interpretación de voz en tiempo real.','No es Comprehend.','No es un chatbot.'],[C('Comprehend','Comprehend analiza; Translate traduce.'),C('Transcribe','Transcribe convierte voz a texto; Translate traduce texto.'),C('Polly','Polly lee el texto traducido.' )],['Amazon S3','AWS Lambda','Amazon Comprehend'],['s50'],12);
  add('ia',['chatbots','lex','Amazon Lex','Chatbots de voz y texto.','Chatbot / intents / slots / conversación.','Lex permite crear bots conversacionales con intenciones y slots, usando voz o texto.','Cuando el examen pide un chatbot o asistente conversacional.','No es un asistente generativo general como Q.','No es un motor de búsqueda.','No es una plataforma para entrenar modelos.'],[C('Q','Q es asistente generativo; Lex es un chatbot configurable.'),C('Comprehend','Comprehend analiza texto; Lex conversa.'),C('Connect','Connect es contact center; Lex puede integrarse en él.' )],['AWS Lambda','Amazon Connect','Amazon Comprehend'],['s50'],12);
  add('ia',['chatbots','q','Amazon Q','Asistente de IA generativa para trabajo y AWS.','Asistente / IA generativa / preguntas / AWS.','Amazon Q es un asistente generativo que responde preguntas, ayuda a escribir y puede apoyar tareas de AWS y de negocio.','Cuando el examen menciona un asistente de IA generativa o ayuda contextual.','No es un modelo fundacional como Bedrock.','No es un chatbot de contacto como Lex.','No es un servicio de visión.'],[C('Bedrock','Bedrock ofrece modelos; Q es un asistente.'),C('Lex','Lex construye chatbots; Q es un asistente listo.'),C('Kendra','Kendra busca conocimiento empresarial; Q genera respuestas.' )],['AWS Lambda','Amazon Bedrock','Amazon S3'],['s50'],12);
  add('ia',['busqueda','kendra','Amazon Kendra','Búsqueda empresarial inteligente.','Búsqueda / conocimiento / documentos / respuestas.','Kendra busca en documentos y fuentes empresariales y devuelve respuestas relevantes con comprensión del lenguaje natural.','Cuando el examen pide búsqueda interna o encontrar respuestas en documentación.','No es OpenSearch para logs.','No es un asistente generativo general.','No es un motor de bases de datos.'],[C('OpenSearch','OpenSearch busca logs/texto; Kendra busca conocimiento empresarial.'),C('Q','Q es asistente; Kendra es búsqueda.'),C('Comprehend','Comprehend analiza; Kendra busca.' )],['Amazon S3','Amazon Q','Amazon Comprehend'],['s50'],12,'Complementario');
  add('ia',['busqueda','personalize','Amazon Personalize','Recomendaciones personalizadas.','Recomendaciones / personalización / usuarios.','Personalize genera recomendaciones personalizadas a partir de datos de interacción, sin construir el modelo desde cero.','Cuando el examen pide recomendaciones de productos o contenido.','No es un chatbot.','No es búsqueda empresarial.','No es un servicio de visión.'],[C('Kendra','Kendra busca; Personalize recomienda.'),C('SageMaker','SageMaker entrena modelos; Personalize está especializado en recomendaciones.'),C('Forecast','Forecast predice series; Personalize recomienda.' )],['Amazon S3','AWS Lambda','Amazon SageMaker AI'],['s50'],12,'Complementario');
  add('ia',['busqueda','forecast','Amazon Forecast','Pronósticos de series temporales.','Pronóstico / demanda / series temporales.','Forecast construye pronósticos de demanda u otras series temporales a partir de datos históricos.','Cuando el examen pide predecir demanda o inventario.','No es un modelo de recomendación.','No es un chatbot.','No es un servicio de analítica de logs.'],[C('Personalize','Personalize recomienda; Forecast pronostica.'),C('SageMaker','SageMaker entrena modelos; Forecast está especializado en series.'),C('QuickSight','QuickSight visualiza; Forecast predice.' )],['Amazon S3','Amazon SageMaker AI','Amazon QuickSight'],['s50'],12,'Complementario');

  // ---------- Integración ----------
  add('integracion',['colas','sqs','Amazon SQS','Cola de mensajes punto a punto.','Cola / desacoplar / consumidor / reintento.','SQS almacena mensajes en una cola para que un consumidor los procese, desacoplando productor y consumidor y permitiendo reintentos.','Cuando el examen pide desacoplar componentes o absorber picos de trabajo.','No es pub/sub para muchos suscriptores.','No es un bus de eventos.','No es un servicio de streaming de datos.'],[C('SNS','SNS publica a muchos; SQS entrega a un consumidor.'),C('EventBridge','EventBridge enruta eventos; SQS encola trabajo.'),C('Kinesis','Kinesis procesa streams; SQS encola mensajes.' )],['AWS Lambda','Amazon EC2','Amazon SNS'],['s51'],12);
  add('integracion',['pubsub','sns','Amazon SNS','Publicación pub/sub a muchos suscriptores.','Pub/sub / notificación / distribución a varios / suscriptor.','SNS envía un mensaje a muchos suscriptores (correo electrónico, SMS, Lambda, SQS, HTTP) mediante temas.','Cuando el examen pide notificar a varios destinos o distribución a varios.','No retiene mensajes para que los leas después como una cola.','No es un bus de eventos con filtros avanzados.','No es un servicio de streaming.'],[C('SQS','SQS es cola; SNS es pub/sub.'),C('EventBridge','EventBridge enruta eventos; SNS notifica.'),C('Lambda','Lambda puede suscribirse a un tema SNS.' )],['AWS Lambda','Amazon SQS','Amazon CloudWatch'],['s51'],12);
  add('integracion',['eventos','eventbridge','Amazon EventBridge','Bus de eventos y reglas.','Eventos / bus / regla / filtro / SaaS (software como servicio).','EventBridge recibe eventos de AWS, aplicaciones o SaaS, los filtra con reglas y los envía a destinos.','Cuando el examen pide reaccionar a cambios de estado o integrar eventos entre servicios.','No es una cola de trabajo.','No es pub/sub simple como SNS.','No es un orquestador de pasos largos.'],[C('SNS','SNS notifica; EventBridge enruta y filtra eventos.'),C('SQS','SQS encola; EventBridge enruta.'),C('Step Functions','Step Functions orquesta; EventBridge dispara.' )],['AWS Lambda','Amazon SQS','AWS Step Functions'],['s51'],12);
  add('integracion',['orquestacion','step-functions','AWS Step Functions','Orquestación de flujos con estado.','Orquestar / flujo de trabajo / estado / reintentos.','Step Functions coordina pasos, decisiones, reintentos y errores entre servicios mediante máquinas de estado.','Cuando el examen pide un flujo con varios pasos o lógica de reintento.','No es una cola de mensajes.','No es un bus de eventos.','No ejecuta la lógica de negocio por sí solo.'],[C('Lambda','Lambda ejecuta pasos; Step Functions los coordina.'),C('EventBridge','EventBridge dispara; Step Functions orquesta.'),C('SQS','SQS encola; Step Functions coordina.' )],['AWS Lambda','Amazon SQS','Amazon EventBridge'],['s51'],12);

