  add('business',['email','ses','Amazon SES','Envío de correo transaccional y masivo.','Email / marketing / transaccional / SMTP.','SES envía y recibe correo electrónico a gran escala, con autenticación y métricas de entrega.','Cuando el examen pide enviar correos transaccionales o de marketing.','No es un cliente de correo corporativo.','No es WorkMail.','No es un servicio de contact center.'],[C('WorkMail','WorkMail es correo corporativo; SES es envío masivo/transaccional.'),C('Connect','Connect es contact center; SES es email.'),C('SNS','SNS notifica por varios canales; SES es correo.' )],['AWS Lambda','Amazon S3','Amazon Connect'],['s68'],12);
  add('business',['contact-center','connect','Amazon Connect','Centro de contacto omnicanal en la nube.','Call center / contact center / voz / chat / omnicanal.','Connect ofrece un centro de contacto en la nube para voz, chat y atención al cliente, con enrutamiento y analítica.','Cuando el examen pide un call center o atención omnicanal.','No es un chatbot por sí solo.','No es un servicio de correo.','No es un CRM completo.'],[C('Lex','Lex puede actuar como bot dentro de Connect.'),C('SES','SES envía email; Connect atiende llamadas/chat.'),C('WorkMail','WorkMail es correo; Connect es contact center.' )],['Amazon Lex','AWS Lambda','Amazon S3'],['s68'],12);

  // ---------- Migración ----------
  add('migracion',['descubrir','application-discovery','AWS Application Discovery Service','Descubre servidores y dependencias para migrar.','Descubrimiento / inventario / dependencias / migración.','Application Discovery Service recopila información de servidores on-premises y sus dependencias para planificar una migración.','Cuando el examen pide inventariar el entorno antes de migrar.','No mueve datos.','No evalúa el costo.','No es Migration Hub.'],[C('Migration Hub','Migration Hub centraliza el seguimiento; Discovery descubre.'),C('Migration Evaluator','Evaluator estima costos; Discovery inventaría.'),C('MGN','MGN migra servidores; Discovery descubre.' )],['AWS Migration Hub','AWS Application Migration Service (MGN)'],['s42'],13);
  add('migracion',['descubrir','migration-evaluator','AWS Migration Evaluator','Caso de negocio y estimación de costo de migración.','Caso de negocio / TCO / estimación / migración.','Migration Evaluator recopila datos y construye una estimación del costo y el business case para migrar a AWS.','Cuando el examen pide justificar la migración o estimar el TCO antes de mover.','No migra.','No descubre dependencias como Discovery.','No es Pricing Calculator.'],[C('Application Discovery Service','Discovery inventaría; Evaluator estima el caso.'),C('TCO','TCO compara; Evaluator construye el business case.'),C('Migration Hub','Hub hace seguimiento; Evaluator evalúa.' )],['AWS Migration Hub','AWS Application Discovery Service','AWS Pricing Calculator'],['s42'],13);
  add('migracion',['servidores','mgn','AWS Application Migration Service (MGN)','Migración de servidores completos a AWS.','Rehost / servidores / replicación / migración.','MGN replica servidores físicos, virtuales o de otras nubes hacia AWS para migrarlos con mínima interrupción.','Cuando el examen pide migrar servidores completos o hacer un Rehost.','No migra bases de datos por sí solo.','No es un servicio de backup.','No es DRS: MGN migra; DRS mantiene un sitio de recuperación.'],[C('DMS','DMS migra bases; MGN migra servidores.'),C('DRS','DRS es DR; MGN es migración definitiva.'),C('Migration Hub','Hub hace seguimiento; MGN ejecuta.' )],['Amazon EC2','Amazon EBS','AWS Migration Hub'],['s42'],13);
  add('migracion',['servidores','migration-hub','AWS Migration Hub','Seguimiento centralizado de migraciones.','Seguimiento / migración / inventario / progreso.','Migration Hub centraliza el progreso de las migraciones y conecta herramientas como MGN, DMS y Discovery.','Cuando el examen pide un único panel para seguir una migración.','No migra por sí solo.','No descubre servidores.','No estima el costo.'],[C('MGN','MGN migra; Hub sigue el progreso.'),C('DMS','DMS migra bases; Hub sigue.'),C('Discovery','Discovery inventaría; Hub centraliza.' )],['AWS Application Migration Service (MGN)','AWS Database Migration Service (DMS)','AWS Application Discovery Service'],['s42'],13);
  add('almacenamiento',['hibrido','snow','AWS Snow Family','Dispositivos físicos para mover datos o computar en el borde.','Snowball / Edge / offline / petabytes.','Snow mueve grandes volúmenes de datos sin depender de la red o ejecuta cómputo en ubicaciones remotas.','Cuando el examen pide migrar petabytes, entornos sin conectividad o cómputo en el borde.','No es almacenamiento permanente en la nube.','No es una conexión VPN.','No es Storage Gateway.'],[C('DataSync','DataSync usa red; Snow es físico.'),C('Storage Gateway','Storage Gateway es híbrido continuo; Snow es transferencia por lotes.'),C('S3','S3 es el destino; Snow transporta.' )],['Amazon S3','AWS Glue','AWS DataSync'],['s42'],13,'Complementario');
  add('migracion',['datos','transfer-family','AWS Transfer Family','Transferencia de archivos por SFTP, FTPS y FTP.','SFTP / FTPS / FTP / S3 / EFS.','Transfer Family permite transferir archivos hacia/desde S3 o EFS usando protocolos SFTP, FTPS y FTP sin administrar servidores.','Cuando el examen pide transferencia de archivos por SFTP o FTP gestionado.','No es un servicio de backup.','No es DataSync.','No es un sistema de archivos.'],[C('DataSync','DataSync automatiza la copia; Transfer Family expone protocolos de archivo.'),C('Storage Gateway','Storage Gateway es híbrido; Transfer Family es transferencia.'),C('S3','S3 es el destino de los archivos.' )],['Amazon S3','Amazon EFS','AWS DataSync'],['s69'],13,'Complementario');

