  add('desarrollo',['entorno','cli','AWS CLI','Interfaz de línea de comandos de AWS.','CLI / terminal / automatizar / scripts.','La AWS CLI permite administrar servicios desde la terminal y automatizar tareas con scripts.','Cuando el examen pide automatizar con comandos o usar una terminal.','No es la consola web.','No es un SDK.','No es CloudShell.'],[C('CloudShell','CloudShell es una terminal en el navegador; CLI es local.'),C('Management Console','La consola es visual; CLI es texto.'),C('SDKs','Los SDKs integran AWS en código; CLI ejecuta comandos.' )],['AWS CloudShell','AWS Management Console','AWS IAM'],['s62'],10);
  add('desarrollo',['entorno','cloud9','AWS Cloud9','IDE en el navegador.','IDE / editor / navegador / desarrollo.','Cloud9 es un entorno de desarrollo integrado en el navegador con editor, terminal y depuración.','Cuando el examen pide un IDE en la nube.','No es un servicio de ejecución de aplicaciones.','No es CloudShell.','No es CodeCommit.'],[C('CloudShell','CloudShell es terminal; Cloud9 es IDE.'),C('CodeCommit','CodeCommit guarda código; Cloud9 lo edita.'),C('CodeBuild','CodeBuild compila; Cloud9 desarrolla.' )],['AWS CloudShell','AWS CodeCommit','AWS CodeBuild'],['s69'],10,'Complementario');
  add('desarrollo',['entorno','cloudshell','AWS CloudShell','Terminal de AWS en el navegador.','Terminal / navegador / CLI preautenticada.','CloudShell ofrece una terminal con AWS CLI ya autenticada desde la consola, sin instalar nada.','Cuando el examen pide ejecutar comandos desde el navegador.','No es un IDE completo.','No es la CLI local.','No es un servicio de cómputo general.'],[C('CLI','La CLI es local; CloudShell está en el navegador.'),C('Cloud9','Cloud9 es IDE; CloudShell es terminal.'),C('Management Console','La consola es visual; CloudShell es texto.' )],['AWS CLI','AWS Management Console','AWS IAM'],['s69'],10,'Complementario');
  add('desarrollo',['cicd','codecommit','AWS CodeCommit','Repositorio Git gestionado.','Git / repositorio / código / privado.','CodeCommit es un repositorio Git privado y gestionado para almacenar código.','Cuando el examen pide un repositorio Git en AWS.','No es un pipeline.','No es un IDE.','No es un registro de imágenes.'],[C('CodePipeline','Pipeline orquesta; CodeCommit guarda código.'),C('CodeBuild','Build compila; Commit almacena.'),C('ECR','ECR guarda imágenes; CodeCommit guarda código.' )],['AWS CodeBuild','AWS CodePipeline','AWS CodeDeploy'],['s67'],10,'Complementario');
  add('desarrollo',['cicd','codebuild','AWS CodeBuild','Compilación y pruebas gestionadas.','Compilación / pruebas / CI (integración continua).','CodeBuild compila código, ejecuta pruebas y produce artefactos sin administrar servidores de build.','Cuando el examen pide compilar o ejecutar tests en CI.','No despliega por sí solo.','No es un repositorio.','No es un pipeline.'],[C('CodePipeline','Pipeline orquesta; CodeBuild compila.'),C('CodeDeploy','Deploy despliega; Build compila.'),C('CodeCommit','Commit guarda; Build compila.' )],['AWS CodeCommit','AWS CodePipeline','AWS CodeDeploy'],['s67'],10);
  add('desarrollo',['cicd','codedeploy','AWS CodeDeploy','Despliegue automatizado de aplicaciones.','Despliegue / EC2 / Lambda / ECS.','CodeDeploy automatiza despliegues en EC2, Lambda, ECS y on-premises, con estrategias y rollback.','Cuando el examen pide desplegar una aplicación de forma automatizada.','No compila.','No es un repositorio.','No es un pipeline.'],[C('CodeBuild','Build compila; Deploy despliega.'),C('CodePipeline','Pipeline orquesta; Deploy ejecuta.'),C('EC2','Deploy instala en instancias.' )],['AWS CodeBuild','AWS CodePipeline','Amazon EC2'],['s67'],10,'Complementario');
  add('desarrollo',['cicd','codepipeline','AWS CodePipeline','Orquestación de CI/CD (integración y entrega continuas).','Pipeline (flujo CI/CD) / etapas / automatización.','CodePipeline modela y ejecuta las etapas de un pipeline: source, build, test y deploy.','Cuando el examen pide un pipeline de entrega continua.','No compila ni despliega por sí solo: usa acciones.','No es un repositorio.','No es un IDE.'],[C('CodeBuild','Build compila; Pipeline orquesta.'),C('CodeDeploy','Deploy despliega; Pipeline coordina.'),C('CodeCommit','Commit es la fuente; Pipeline la usa.' )],['AWS CodeCommit','AWS CodeBuild','AWS CodeDeploy'],['s67'],10);
  add('desarrollo',['cicd','codeartifact','AWS CodeArtifact','Repositorio de paquetes y dependencias.','Paquetes / npm / pip / Maven / artefactos.','CodeArtifact almacena y gestiona paquetes de software (npm, pip, Maven, etc.) de forma privada.','Cuando el examen pide un repositorio privado de paquetes.','No es un repositorio Git.','No es un registro de imágenes.','No es un pipeline.'],[C('ECR','ECR guarda imágenes; CodeArtifact guarda paquetes.'),C('CodeCommit','CodeCommit guarda código; CodeArtifact dependencias.'),C('CodeBuild','Build descarga paquetes de Artifact.' )],['AWS CodeBuild','AWS CodePipeline','Amazon ECR'],['s69'],10,'Complementario');
  add('desarrollo',['cicd','codestar','AWS CodeStar','Plantillas y proyecto integrado para CI/CD.','Plantilla / proyecto / CI/CD / rápido.','CodeStar ofrece plantillas y un proyecto integrado para configurar rápidamente CI/CD y herramientas de desarrollo.','Cuando el examen pide una forma rápida de iniciar un proyecto con CI/CD.','No es un repositorio Git por sí solo.','No es un pipeline genérico.','No es un IDE.'],[C('CodePipeline','Pipeline es la orquestación; CodeStar es el proyecto/plantilla.'),C('CodeCommit','Commit guarda el código; CodeStar lo integra.'),C('Cloud9','Cloud9 edita; CodeStar organiza.' )],['AWS CodeCommit','AWS CodePipeline','AWS Cloud9'],['s67'],10,'Complementario');
