  add('desarrollo',['config','appconfig','AWS AppConfig','Despliegue de configuración validada.','Configuración / feature flag (indicador de funcionalidad) / validar / sin redesplegar.','AppConfig permite desplegar cambios de configuración de forma controlada, validada y con rollback, sin redesplegar el código.','Cuando el examen pide cambiar configuración sin nuevo despliegue.','No es un repositorio de código.','No es un pipeline completo.','No es Parameter Store.'],[C('Parameter Store','Parameter Store guarda parámetros; AppConfig despliega configuración.'),C('CodePipeline','Pipeline despliega código; AppConfig configura.'),C('CloudFormation','CloudFormation crea infraestructura; AppConfig cambia parámetros.' )],['AWS Lambda','Amazon EC2','AWS CodePipeline'],['s69'],10,'Complementario');

