  add('euc',['escritorios','workspaces','Amazon WorkSpaces','Escritorio virtual completo en la nube.','VDI (escritorio virtual) / Windows / Linux / remoto.','WorkSpaces entrega un escritorio Windows o Linux completo y persistente a empleados remotos.','Cuando el examen pide un escritorio virtual completo para empleados.','No es solo streaming de una aplicación.','No es un navegador aislado.','No es un servicio de contact center.'],[C('AppStream 2.0','AppStream publica una sola app; WorkSpaces da el escritorio completo.'),C('WorkSpaces Secure Browser','Secure Browser aísla la web; WorkSpaces da el desktop.'),C('EC2','EC2 es un servidor; WorkSpaces es un escritorio gestionado.' )],['AWS Directory Service','Amazon VPC','Amazon WorkMail'],['s68'],12);
  add('euc',['apps','appstream','Amazon AppStream 2.0','Streaming de aplicaciones de escritorio.','Streaming / aplicación / navegador / sin instalar.','AppStream 2.0 transmite una aplicación de escritorio concreta al navegador, sin instalar la app en el dispositivo.','Cuando el examen pide publicar solo una aplicación pesada o especializada.','No entrega un escritorio completo.','No es un navegador aislado.','No es WorkSpaces.'],[C('WorkSpaces','WorkSpaces da el escritorio; AppStream solo la app.'),C('WorkSpaces Secure Browser','Secure Browser aísla la web; AppStream publica apps.'),C('EC2','EC2 aloja la app; AppStream la transmite.' )],['Amazon S3','AWS Directory Service','Amazon VPC'],['s68'],12);
  add('euc',['navegador','workspaces-secure-browser','Amazon WorkSpaces Secure Browser','Navegador aislado para acceso web seguro.','Navegador / aislamiento / SaaS (software como servicio) / sin VPN.','WorkSpaces Secure Browser ofrece un navegador aislado para acceder a sitios internos y SaaS sin exponer el dispositivo ni depender de VPN.','Cuando el examen pide navegación web aislada o acceso seguro a SaaS.','No es un escritorio completo.','No es AppStream.','No es un proxy VPN.'],[C('WorkSpaces','WorkSpaces es desktop; Secure Browser solo navegador.'),C('AppStream','AppStream publica apps; Secure Browser publica web.'),C('Client VPN','Client VPN da red; Secure Browser aísla la sesión web.' )],['Amazon VPC','AWS Directory Service','Amazon S3'],['s68'],12);
  add('euc',['productividad','workmail','Amazon WorkMail','Correo y calendario gestionados.','Email corporativo / calendario / Exchange.','WorkMail ofrece correo electrónico y calendario gestionados con compatibilidad con clientes de correo y Active Directory.','Cuando el examen pide correo corporativo gestionado.','No es SES para envío masivo.','No es Gmail/Outlook.','No es un servicio de contact center.'],[C('SES','SES envía correo; WorkMail es buzón corporativo.'),C('Connect','Connect atiende clientes; WorkMail es correo interno.'),C('Directory Service','Directory Service autentica; WorkMail aloja el correo.' )],['AWS Directory Service','Amazon SES','Amazon WorkSpaces'],['s68'],12,'Complementario');
  add('euc',['productividad','chime','Amazon Chime','Reuniones, chat y videollamadas.','Reuniones / videollamada / chat / colaboración.','Chime ofrece reuniones, videollamadas y chat para equipos, con integración a calendarios y directorios.','Cuando el examen pide colaboración o videoconferencia gestionada.','No es un contact center.','No es WorkMail.','No es un servicio de streaming de aplicaciones.'],[C('Connect','Connect es contact center; Chime es colaboración interna.'),C('WorkMail','WorkMail es correo; Chime es reuniones/chat.'),C('AppStream','AppStream publica apps; Chime comunica.' )],['AWS Directory Service','Amazon WorkMail','Amazon Connect'],['s68'],12,'Complementario');

