  add('frontend',['deploy','amplify','AWS Amplify','Despliegue de aplicaciones web y móviles.','Frontend / alojamiento / CI/CD / web / móvil.','Amplify ofrece alojamiento y herramientas para construir y desplegar aplicaciones web y móviles con integración a Cognito, AppSync, S3 y otros servicios.','Cuando el examen pide desplegar una aplicación frontend o móvil.','No es una API GraphQL.','No es un servicio de dispositivos.','No es API Gateway.'],[C('AppSync','AppSync ofrece GraphQL; Amplify despliega el frontend.'),C('Cognito','Cognito autentica; Amplify integra la autenticación.'),C('S3','S3 puede hospedar estáticos; Amplify añade CI/CD y un marco de trabajo.' )],['Amazon Cognito','AWS AppSync','Amazon S3'],['s69'],12);
  add('frontend',['graphql','appsync','AWS AppSync','APIs GraphQL serverless.','GraphQL / API / tiempo real / serverless.','AppSync crea APIs GraphQL gestionadas con acceso a datos en tiempo real y resolución a DynamoDB, Lambda u otras fuentes.','Cuando el examen pide GraphQL o una API en tiempo real.','No es REST como API Gateway.','No es una base de datos.','No es un frontend.'],[C('API Gateway','API Gateway es REST/HTTP; AppSync es GraphQL.'),C('DynamoDB','DynamoDB es la fuente de datos; AppSync la expone.'),C('Amplify','Amplify despliega el cliente; AppSync la API.' )],['Amazon DynamoDB','AWS Lambda','Amazon Cognito'],['s69'],12,'Complementario');
  add('frontend',['testing','device-farm','AWS Device Farm','Pruebas en dispositivos reales.','Pruebas / dispositivos / móvil / web.','Device Farm ejecuta pruebas automatizadas o manuales en una flota de teléfonos y tabletas reales.','Cuando el examen pide probar aplicaciones en dispositivos reales.','No es un emulador local.','No es un servicio de despliegue.','No es AppStream.'],[C('AppStream','AppStream publica aplicaciones; Device Farm las prueba.'),C('Amplify','Amplify despliega; Device Farm prueba.'),C('EC2','EC2 es cómputo; Device Farm es pruebas.' )],['AWS Amplify','AWS Device Farm','Amazon S3'],['s69'],12,'Complementario');

