  add('iot',['core','iot-core','AWS IoT Core','Conecta dispositivos IoT con AWS.','IoT / MQTT / dispositivos / telemetría.','IoT Core conecta y gestiona dispositivos, recibe telemetría y enruta mensajes hacia otros servicios de AWS.','Cuando el examen pide conectar sensores o dispositivos a la nube.','No ejecuta cómputo local en el dispositivo.','No es Greengrass.','No es un servicio de analítica.'],[C('Greengrass','Greengrass ejecuta cómputo local; IoT Core conecta.'),C('Kinesis','Kinesis procesa streams; IoT Core conecta dispositivos.'),C('S3','S3 almacena; IoT Core ingiere.' )],['AWS Lambda','Amazon Kinesis','Amazon S3'],['s68'],12);
